def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Connect aligned occurrences of the same non-background color with color 3.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for cc in range(c + 1, w):
                if grid[r][cc] == color:
                    for x in range(c + 1, cc):
                        if grid[r][x] == bg:
                            out[r][x] = 3
            for rr in range(r + 1, h):
                if grid[rr][c] == color:
                    for y in range(r + 1, rr):
                        if grid[y][c] == bg:
                            out[y][c] = 3
    return out

